import{_ as d,c as r,o as n,a4 as e}from"./chunks/framework.C-Sv_Sou.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"md-ai/noun-explanation.md","filePath":"md-ai/noun-explanation.md","lastUpdated":1783862120000}'),a={name:"md-ai/noun-explanation.md"};function o(i,t,s,l,g,c){return n(),r("div",null,[...t[0]||(t[0]=[e('<p>以下是以表格形式整理的AI技术基础知识及核心名词解释，涵盖基础概念、学习范式、模型类型、关键术语等维度。</p><table tabindex="0"><thead><tr><th>类别</th><th>术语</th><th>英文</th><th>简要解释</th></tr></thead><tbody><tr><td><strong>基础概念</strong></td><td>人工智能</td><td>Artificial Intelligence (AI)</td><td>让机器模拟人类智能（如学习、推理、感知）的学科。</td></tr><tr><td></td><td>机器学习</td><td>Machine Learning (ML)</td><td>AI的子集，让机器从数据中自动学习规律，而非通过硬编码规则。</td></tr><tr><td></td><td>深度学习</td><td>Deep Learning (DL)</td><td>基于多层神经网络的一种机器学习方法，擅长处理图像、语音等复杂数据。</td></tr><tr><td></td><td>弱人工智能</td><td>Narrow AI</td><td>专注于特定任务（如人脸识别、下棋），目前所有商用AI都属于此类。</td></tr><tr><td></td><td>强人工智能</td><td>General AI (AGI)</td><td>具备与人类同等水平的通用智能，能完成任何智力任务，目前尚未实现。</td></tr><tr><td><strong>学习范式</strong></td><td>监督学习</td><td>Supervised Learning</td><td>使用带标签的数据训练模型（输入→输出对应），如分类、回归。</td></tr><tr><td></td><td>无监督学习</td><td>Unsupervised Learning</td><td>使用无标签数据，让模型自行发现结构（如聚类、降维）。</td></tr><tr><td></td><td>强化学习</td><td>Reinforcement Learning (RL)</td><td>智能体通过与环境互动、试错并获取奖励来学习最优策略。</td></tr><tr><td></td><td>半监督学习</td><td>Semi-supervised Learning</td><td>结合少量标签数据和大量无标签数据进行训练。</td></tr><tr><td></td><td>自监督学习</td><td>Self-supervised Learning</td><td>从数据自身构造标签（如预测句子中遮罩的词），近年大模型的核心方法。</td></tr><tr><td><strong>模型与架构</strong></td><td>神经网络</td><td>Neural Network</td><td>模拟生物神经元连接的计算模型，由输入层、隐藏层、输出层组成。</td></tr><tr><td></td><td>深度神经网络</td><td>Deep Neural Network (DNN)</td><td>具有多个隐藏层的神经网络，深度学习的基础。</td></tr><tr><td></td><td>卷积神经网络</td><td>Convolutional Neural Network (CNN)</td><td>擅长提取局部空间特征，主要应用于图像、视频处理。</td></tr><tr><td></td><td>循环神经网络</td><td>Recurrent Neural Network (RNN)</td><td>具有循环连接，适合处理序列数据（如文本、时间序列）。</td></tr><tr><td></td><td>长短期记忆网络</td><td>Long Short-Term Memory (LSTM)</td><td>一种特殊的RNN，解决长序列中的梯度消失问题。</td></tr><tr><td></td><td>注意力机制</td><td>Attention Mechanism</td><td>让模型动态聚焦关键信息，Transformer的核心组件。</td></tr><tr><td></td><td>Transformer</td><td>Transformer</td><td>完全基于自注意力的架构，抛弃RNN，成为大语言模型的基础。</td></tr><tr><td><strong>关键术语</strong></td><td>训练 / 推理</td><td>Training / Inference</td><td>训练：用数据更新模型参数的过程；推理：用训练好的模型对新样本做预测。</td></tr><tr><td></td><td>特征</td><td>Feature</td><td>用于预测的输入变量（如房价预测中的面积、房间数）。</td></tr><tr><td></td><td>标签</td><td>Label</td><td>监督学习中的目标输出（即要预测的真实值）。</td></tr><tr><td></td><td>损失函数</td><td>Loss Function</td><td>衡量模型预测与真实值之间差距的函数，训练的目标是最小化损失。</td></tr><tr><td></td><td>优化器</td><td>Optimizer</td><td>根据损失函数梯度更新模型参数的算法（如SGD、Adam）。</td></tr><tr><td></td><td>过拟合 / 欠拟合</td><td>Overfitting / Underfitting</td><td>过拟合：模型过度学习训练集细节，对新数据泛化差；欠拟合：连训练集规律都没学好。</td></tr><tr><td></td><td>正则化</td><td>Regularization</td><td>防止过拟合的技术，如L1/L2正则化、Dropout、早停法。</td></tr><tr><td></td><td>激活函数</td><td>Activation Function</td><td>为神经网络引入非线性，如ReLU、Sigmoid、Tanh。</td></tr><tr><td></td><td>反向传播</td><td>Backpropagation</td><td>计算损失函数对各层参数梯度的算法，用于更新权重。</td></tr><tr><td></td><td>学习率</td><td>Learning Rate</td><td>优化器更新参数的步长，影响收敛速度和效果。</td></tr><tr><td></td><td>批大小 / 轮次</td><td>Batch Size / Epoch</td><td>批大小：一次前向传播所用的样本数；轮次：完整遍历整个训练集的次数。</td></tr><tr><td><strong>生成式AI</strong></td><td>生成对抗网络</td><td>Generative Adversarial Network (GAN)</td><td>包含生成器与判别器两者对抗训练，能生成逼真的图像、音频。</td></tr><tr><td></td><td>变分自编码器</td><td>Variational Autoencoder (VAE)</td><td>学习潜在空间分布并从中采样以生成新数据。</td></tr><tr><td></td><td>大语言模型</td><td>Large Language Model (LLM)</td><td>基于海量文本训练的巨型Transformer模型，如GPT、LLaMA、文心一言。</td></tr><tr><td></td><td>扩散模型</td><td>Diffusion Model</td><td>通过逐步加噪再逆转去噪生成高质量图像（如DALL·E、Stable Diffusion）。</td></tr><tr><td></td><td>提示学习</td><td>Prompt Learning</td><td>设计合适的输入提示来引导大模型完成特定任务，不需微调参数。</td></tr><tr><td><strong>数据与工程</strong></td><td>训练集 / 验证集 / 测试集</td><td>Train / Validation / Test Set</td><td>训练集用于拟合参数，验证集用于调参和选模型，测试集用于最终评估泛化能力。</td></tr><tr><td></td><td>数据增强</td><td>Data Augmentation</td><td>对原始数据进行变换（如旋转、裁剪图像）以增加训练样本多样性。</td></tr><tr><td></td><td>嵌入</td><td>Embedding</td><td>将离散变量（如单词、商品ID）映射为连续低维向量，表达语义关系。</td></tr><tr><td></td><td>归一化 / 标准化</td><td>Normalization / Standardization</td><td>将数据缩放到相似范围，以加速训练收敛。</td></tr><tr><td></td><td>端到端学习</td><td>End-to-End Learning</td><td>直接从原始输入到最终输出的整体优化，无需分模块处理。</td></tr><tr><td><strong>评估指标</strong></td><td>准确率</td><td>Accuracy</td><td>分类正确的样本数 / 总样本数。</td></tr><tr><td></td><td>精确率 / 召回率 / F1分数</td><td>Precision / Recall / F1-Score</td><td>精确率：预测为正类中实际为正的比例；召回率：实际正类中被预测出的比例；F1：两者的调和平均。</td></tr><tr><td></td><td>混淆矩阵</td><td>Confusion Matrix</td><td>展示真实类别与预测类别对应关系的表格（TP、FN、FP、TN）。</td></tr><tr><td></td><td>ROC曲线 / AUC</td><td>ROC Curve / AUC</td><td>衡量二分类模型在不同阈值下性能的综合指标，AUC越接近1越好。</td></tr><tr><td><strong>前沿与伦理</strong></td><td>可解释性AI</td><td>Explainable AI (XAI)</td><td>试图解释“黑箱”模型做出某个决策的原因。</td></tr><tr><td></td><td>联邦学习</td><td>Federated Learning</td><td>在不集中交换原始数据的前提下，多方协同训练模型，保护隐私。</td></tr><tr><td></td><td>对齐</td><td>AI Alignment</td><td>确保AI系统的目标与人类价值观和意图保持一致。</td></tr><tr><td></td><td>幻觉</td><td>Hallucination</td><td>大模型生成看似合理但不符合事实或输入的虚构内容。</td></tr></tbody></table>',2)])])}const p=d(a,[["render",o]]);export{A as __pageData,p as default};
